class Solution {
public:
    vector<int> shortestToChar(string s, char c) {
        int n = s.size(), last = -100000;
        vector<int> res(n);
        for (int i = 0; i < n; i++) {
            if (s[i] == c) last = i;
            res[i] = i - last;
        }
        last = 200000;
        for (int i = n - 1; i >= 0; i--) {
            if (s[i] == c) last = i;
            res[i] = min(res[i], last - i);
        }
        return res;
    }
};
